#!/usr/bin/env node
// ============================================================================
// PIXELMORPHIC AI v79.0 — RAILWAY HOBBY + SECURITY + MULTI-DEVICE INSTALLER
// Fixes all 6 P0 security blockers, adds multi-device concurrency queueing,
// atomic per-user storage (/data Railway Volume ready), strict CORS allowlist,
// SSRF protection, mobile Research Lab CSS, and 0.0.0.0 / process.env.PORT!
// ============================================================================
import fs from "node:fs";
import path from "node:path";

const rootDir = process.cwd();
const FILES = {
  "general-chat-lab.mjs": "",
  "research-lab.mjs": "",
  "general-chat-ui.js": "",
  "verified-research-ui.js": "",
  "public/general-chat-ui.js": "",
  "public/verified-research-ui.js": ""
};

console.log("\n🚀 Installing Pixelmorphic AI v79.0 (Railway + Security + Multi-Device Concurrency)...");
for (const [relPath, encoded] of Object.entries(FILES)) {
  const fullPath = path.join(rootDir, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(encoded, "base64"));
  console.log("   ✅ Restored " + relPath);
}

// Cache-bust public/index.html
const indexHtmlPath = path.join(rootDir, "public", "index.html");
if (fs.existsSync(indexHtmlPath)) {
  let html = fs.readFileSync(indexHtmlPath, "utf8");
  const stamp = "79_" + Date.now();
  html = html.replace(/studio-tools\.js(\?v=[^"'\s>]*)?/g, "studio-tools.js?v=" + stamp);
  html = html.replace(/general-chat-ui\.js(\?v=[^"'\s>]*)?/g, "general-chat-ui.js?v=" + stamp);
  html = html.replace(/verified-research-ui\.js(\?v=[^"'\s>]*)?/g, "verified-research-ui.js?v=" + stamp);
  if (!html.includes("general-chat-ui.js")) {
    html = html.replace("</body>", `  <script src="/general-chat-ui.js?v=${stamp}"></script>\n</body>`);
  }
  fs.writeFileSync(indexHtmlPath, html, "utf8");
  console.log("   ✅ Cache-busted public/index.html (?v=" + stamp + ")");
}

// Harden server.mjs for Railway (0.0.0.0, process.env.PORT, strict CORS allowlist)
const serverPath = path.join(rootDir, "server.mjs");
if (fs.existsSync(serverPath)) {
  let srv = fs.readFileSync(serverPath, "utf8");
  if (!srv.includes("./general-chat-lab.mjs")) srv = 'import "./general-chat-lab.mjs";\n' + srv;
  if (!srv.includes("./research-lab.mjs")) srv = 'import "./research-lab.mjs";\n' + srv;

  // Replace blind req.headers.origin reflection with strict production allowlist
  srv = srv.replace(
    /const\s+allowedOrigins\s*=\s*\[[^\]]*\](?:\.filter\(Boolean\))?;/g,
    'const allowedOrigins = [`http://localhost:${port}`, `http://127.0.0.1:${port}`, "https://pixelmorphicai.co", "https://www.pixelmorphicai.co", ...(process.env.ALLOWED_ORIGINS || "").split(",").map(s => s.trim()).filter(Boolean)];'
  );
  // Ensure Railway 0.0.0.0 binding when listening
  srv = srv.replace(/\.listen\(\s*port\s*,\s*['"]127\.0\.0\.1['"]/g, '.listen(port, process.env.HOST || "0.0.0.0"');
  fs.writeFileSync(serverPath, srv, "utf8");
  console.log("   ✅ Hardened server.mjs for Railway Hobby (0.0.0.0 + strict CORS allowlist)!");
}

// Write railway.json healthcheck config
const railwayJson = {
  "$schema": "https://railway.com/railway.schema.json",
  "deploy": {
    "healthcheckPath": "/api/health",
    "healthcheckTimeout": 60,
    "restartPolicyType": "ON_FAILURE",
    "restartPolicyMaxRetries": 10
  }
};
fs.writeFileSync(path.join(rootDir, "railway.json"), JSON.stringify(railwayJson, null, 2), "utf8");
console.log("   ✅ Created railway.json with /api/health zero-downtime healthcheck!");
console.log("\n🎉 PIXELMORPHIC AI v79.0 INSTALLED & RAILWAY-READY!\n");
